import React, { useState } from "react";
import { Calendar, Clock, MapPin } from "lucide-react";
import { motion } from "framer-motion";

const BookingView = () => {
  const [selectedSport, setSelectedSport] = useState("");
  const [selectedDate, setSelectedDate] = useState("");
  const [selectedTime, setSelectedTime] = useState("");
  const [selectedCourt, setSelectedCourt] = useState("");

  const sports = ["Fútbol", "Baloncesto", "Tenis"];
  const times = ["08:00 AM", "10:00 AM", "12:00 PM", "02:00 PM", "04:00 PM"];
  const courts = ["Cancha 1", "Cancha 2", "Cancha 3"];

  return (
    <div className="min-h-screen flex flex-col bg-gray-50">
      {/* 🟢 NAVBAR IGUAL A LA VISTA 1 */}
      <nav className="bg-gradient-to-r from-green-500 to-green-600 text-white px-6 py-4 flex justify-between items-center shadow-md">
        <div className="flex items-center space-x-3">
          <img
            src="/logo.png"
            alt="Logo"
            className="h-10 w-10 rounded-full border border-white shadow-sm"
          />
          <h1 className="text-2xl font-bold">CanchaYa</h1>
        </div>
        <div className="flex space-x-6 font-medium">
          <a href="#" className="hover:text-green-200 transition">
            Inicio
          </a>
          <a href="#" className="hover:text-green-200 transition">
            Reservas
          </a>
          <a href="#" className="hover:text-green-200 transition">
            Contacto
          </a>
        </div>
        <button className="bg-white text-green-600 font-semibold px-4 py-2 rounded-full shadow hover:bg-green-100 transition">
          Iniciar sesión
        </button>
      </nav>

      {/* 🟩 CONTENIDO PRINCIPAL */}
      <main className="flex-grow flex flex-col items-center justify-center p-6 space-y-8">
        {/* 🟢 BLOQUE 1 - Selección de deporte */}
        <motion.div
          className="bg-white p-6 rounded-2xl shadow-md w-full max-w-md text-center"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
        >
          <h2 className="text-xl font-bold text-gray-800 mb-4">
            Selecciona un deporte
          </h2>
          <select
            className="border border-gray-300 rounded-lg p-2 w-full focus:ring-2 focus:ring-green-500 outline-none"
            value={selectedSport}
            onChange={(e) => setSelectedSport(e.target.value)}
          >
            <option value="">-- Selecciona un deporte --</option>
            {sports.map((sport) => (
              <option key={sport} value={sport}>
                {sport}
              </option>
            ))}
          </select>
        </motion.div>

        {/* 🟢 BLOQUE 2 - Selección de fecha y horario */}
        {selectedSport && (
          <motion.div
            className="bg-white p-6 rounded-2xl shadow-md w-full max-w-md text-center"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex justify-center items-center space-x-2">
              <Calendar className="h-5 w-5 text-green-600" />
              <span>Selecciona una fecha</span>
            </h2>
            <input
              type="date"
              className="border border-gray-300 rounded-lg p-2 w-full focus:ring-2 focus:ring-green-500 outline-none"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />

            {/* Mostrar horarios solo si ya hay fecha seleccionada */}
            {selectedDate && (
              <motion.div
                className="mt-6"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
              >
                <h3 className="text-lg font-semibold text-gray-800 mb-3 flex justify-center items-center space-x-2">
                  <Clock className="h-5 w-5 text-green-600" />
                  <span>Selecciona un horario</span>
                </h3>
                <div className="grid grid-cols-2 gap-3">
                  {times.map((time) => (
                    <button
                      key={time}
                      onClick={() => setSelectedTime(time)}
                      className={`p-2 rounded-lg border font-medium transition ${
                        selectedTime === time
                          ? "bg-green-500 text-white border-green-500"
                          : "bg-gray-50 hover:bg-green-100 border-gray-300 text-gray-700"
                      }`}
                    >
                      {time}
                    </button>
                  ))}
                </div>
              </motion.div>
            )}
          </motion.div>
        )}

        {/* 🟢 BLOQUE 3 - Selección de cancha */}
        {selectedTime && (
          <motion.div
            className="bg-white p-6 rounded-2xl shadow-md w-full max-w-md text-center"
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex justify-center items-center space-x-2">
              <MapPin className="h-5 w-5 text-green-600" />
              <span>Selecciona una cancha</span>
            </h2>
            <div className="grid grid-cols-1 gap-3">
              {courts.map((court) => (
                <button
                  key={court}
                  onClick={() => setSelectedCourt(court)}
                  className={`p-3 rounded-lg border font-medium transition ${
                    selectedCourt === court
                      ? "bg-green-500 text-white border-green-500"
                      : "bg-gray-50 hover:bg-green-100 border-gray-300 text-gray-700"
                  }`}
                >
                  {court}
                </button>
              ))}
            </div>
          </motion.div>
        )}
      </main>

      {/* 🟢 FOOTER (opcional si quieres mantener consistencia) */}
      <footer className="bg-white text-gray-600 py-4 text-center border-t">
        <p className="text-sm">© 2025 CanchaYa. Todos los derechos reservados.</p>
      </footer>
    </div>
  );
};

export default BookingView;
